{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "lg"
      },
      "children": [
        "title_text",
        "env_permissions_stack",
        "active_scanning_modes_stack",
        "quick_actions_stack"
      ]
    },
    "title_text": {
      "type": "Text",
      "props": {
        "text": "Universal Scanner Activation",
        "variant": "h1"
      },
      "children": []
    },
    "env_permissions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "env_permissions_title",
        "env_permissions_text1",
        "env_permissions_text2",
        "env_permissions_text3"
      ]
    },
    "env_permissions_title": {
      "type": "Text",
      "props": {
        "text": "Scanning Environment and Permissions",
        "variant": "h2"
      },
      "children": []
    },
    "env_permissions_text1": {
      "type": "Text",
      "props": {
        "text": "This response assumes the user is operating a mobile device with a functional rear-facing camera."
      },
      "children": []
    },
    "env_permissions_text2": {
      "type": "Text",
      "props": {
        "text": "It is assumed that \"linear barcodes\" refer to standard retail symbologies such as UPC-A, UPC-E, or EAN-13 used for product identification."
      },
      "children": []
    },
    "env_permissions_text3": {
      "type": "Text",
      "props": {
        "text": "Camera permissions must be granted to the browser or host application to enable video capture for decoding."
      },
      "children": []
    },
    "active_scanning_modes_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "active_scanning_modes_title",
        "option1_card",
        "option2_card",
        "option3_card"
      ]
    },
    "active_scanning_modes_title": {
      "type": "Text",
      "props": {
        "text": "Active Scanning Modes",
        "variant": "h2"
      },
      "children": []
    },
    "option1_card": {
      "type": "Card",
      "props": {},
      "children": [
        "option1_content_stack"
      ]
    },
    "option1_content_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "option1_icon",
        "option1_title",
        "option1_desc",
        "option1_button"
      ]
    },
    "option1_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000090_01_3_upc-scan.svg"
      },
      "children": []
    },
    "option1_title": {
      "type": "Text",
      "props": {
        "text": "Web-Based Universal Scanner",
        "variant": "h3"
      },
      "children": []
    },
    "option1_desc": {
      "type": "Text",
      "props": {
        "text": "Recognizes standard QR codes and linear barcodes via browser | Instant access without installation"
      },
      "children": []
    },
    "option1_button": {
      "type": "Button",
      "props": {
        "label": "Launch Web Scanner"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://qrcodescan.in/"
          }
        }
      },
      "children": []
    },
    "option2_card": {
      "type": "Card",
      "props": {},
      "children": [
        "option2_content_stack"
      ]
    },
    "option2_content_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "option2_icon",
        "option2_title",
        "option2_desc",
        "option2_button"
      ]
    },
    "option2_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000175_01_1_camera.svg"
      },
      "children": []
    },
    "option2_title": {
      "type": "Text",
      "props": {
        "text": "Retail Price Search",
        "variant": "h3"
      },
      "children": []
    },
    "option2_desc": {
      "type": "Text",
      "props": {
        "text": "Manual lookup or barcode entry for price comparison | Aggregated retail data"
      },
      "children": []
    },
    "option2_button": {
      "type": "Button",
      "props": {
        "label": "Check Prices"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://shopping.google.com/"
          }
        }
      },
      "children": []
    },
    "option3_card": {
      "type": "Card",
      "props": {},
      "children": [
        "option3_content_stack"
      ]
    },
    "option3_content_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "option3_icon",
        "option3_title",
        "option3_desc",
        "option3_button"
      ]
    },
    "option3_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_001502_01_3_bag-check.svg"
      },
      "children": []
    },
    "option3_title": {
      "type": "Text",
      "props": {
        "text": "Advanced Scanner Application",
        "variant": "h3"
      },
      "children": []
    },
    "option3_desc": {
      "type": "Text",
      "props": {
        "text": "Dedicated tool for rapid batch scanning and history | Offline capability"
      },
      "children": []
    },
    "option3_button": {
      "type": "Button",
      "props": {
        "label": "Install Scanner App"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://play.google.com/store/apps/details?id=com.google.zxing.client.android"
          }
        }
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "quick_actions_title",
        "quick_action_button1",
        "quick_action_button2"
      ]
    },
    "quick_actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "quick_action_button1": {
      "type": "Button",
      "props": {
        "label": "Troubleshooting Camera"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://support.google.com/android/answer/9334246?hl=en"
          }
        }
      },
      "children": []
    },
    "quick_action_button2": {
      "type": "Button",
      "props": {
        "label": "Barcode Standards Info"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.gs1.org/standards/barcodes"
          }
        }
      },
      "children": []
    }
  }
}
